-- MVP production foundation; reuse public.user_profiles, never create a second profile system.
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
alter table public.user_profiles add column if not exists avatar_url text;
alter table public.user_profiles add column if not exists created_at timestamptz not null default now();
alter table public.user_profiles add column if not exists updated_at timestamptz not null default now();
create table if not exists public.user_roles (user_id uuid primary key references public.user_profiles(id) on delete cascade, role text not null check(role in ('client','admin')), granted_by uuid references public.user_profiles(id), created_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 100), description text not null default '', image text not null default '', category text not null default '', tag text not null default '', available boolean not null default true, created_by uuid references public.user_profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.product_plans (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), name text not null, duration_seconds bigint check(duration_seconds > 0), price_cents integer not null check(price_cents > 0), currency text not null default 'USD' check(currency='USD'), created_at timestamptz not null default now());
create table if not exists public.reseller_access (id uuid primary key default gen_random_uuid(), user_id uuid references public.user_profiles(id), access_type text not null default 'standard', starts_at timestamptz not null, ends_at timestamptz not null check(ends_at > starts_at), status text not null default 'active' check(status in ('active','suspended','revoked','expired')), key_hash text unique, key_hint text, redeemed_at timestamptz, granted_by uuid not null references public.user_profiles(id), allowed_products uuid[] not null default '{}', max_quantity integer not null default 10 check(max_quantity between 1 and 100), quota integer not null default 100 check(quota between 1 and 10000), max_duration_seconds bigint not null default 2592000 check(max_duration_seconds>0), allow_lifetime boolean not null default false, grace_until timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.licenses (id uuid primary key default gen_random_uuid(), key_hash text not null unique, key_hint text not null, product_id uuid not null references public.products(id), creator_id uuid not null references public.user_profiles(id), owner_id uuid references public.user_profiles(id), reseller_access_id uuid references public.reseller_access(id), duration_seconds bigint check(duration_seconds>0), activation_limit integer not null default 1 check(activation_limit between 1 and 100), activation_count integer not null default 0 check(activation_count>=0 and activation_count<=activation_limit), status text not null default 'available' check(status in ('available','active','redeemed','expired','banned','revoked')), prior_status text, redeem_before timestamptz, ban_reason text, note text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.license_activations (id uuid primary key default gen_random_uuid(), license_id uuid not null references public.licenses(id), user_id uuid not null references public.user_profiles(id), product_id uuid not null references public.products(id), activated_at timestamptz not null default now(), expires_at timestamptz, build_id text not null default ('MVP-LDR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), unique(license_id,user_id));
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_profiles(id), product_id uuid not null references public.products(id), activation_id uuid not null unique references public.license_activations(id), provider_reference text, status text not null default 'active' check(status in ('active','trialing','past_due','cancelled','expired','suspended')), starts_at timestamptz not null default now(), expires_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), reference text not null unique default ('MVP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), user_id uuid not null references public.user_profiles(id), amount_cents integer not null check(amount_cents>0), currency text not null default 'USD' check(currency='USD'), status text not null default 'pending' check(status in ('pending','paid','failed','cancelled','refunded','fulfilled')), proof_path text not null, notes text not null default '' check(length(notes)<=1000), method text not null check(method in ('PayPal','Cash App')), idempotency_key uuid not null unique, reviewed_by uuid references public.user_profiles(id), reviewed_at timestamptz, rejection_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), product_id uuid not null references public.products(id), plan_id uuid not null references public.product_plans(id), quantity integer not null default 1 check(quantity=1), unit_price_cents integer not null, license_id uuid unique references public.licenses(id));
create table if not exists public.product_files (id uuid primary key default gen_random_uuid(), product_id uuid references public.products(id), name text not null check(length(name) between 2 and 100), image text not null default '', kind text not null check(kind in ('product','setup')), storage_path text, external_url text, enabled boolean not null default true, created_by uuid not null references public.user_profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((kind='product' and product_id is not null and storage_path is not null and external_url is null) or (kind='setup' and product_id is null and external_url like 'https://%' and storage_path is null)));
create table if not exists public.store_settings (id text primary key check(id='payments'), value jsonb not null default '{}', updated_at timestamptz not null default now());
create table if not exists public.xp_accounts (user_id uuid primary key references public.user_profiles(id) on delete cascade, balance bigint not null default 0 check(balance>=0), total_earned bigint not null default 0 check(total_earned>=0), updated_at timestamptz not null default now());
create table if not exists public.xp_claim_types (id text primary key, name text not null, reward integer not null check(reward between 1 and 10000), cooldown_seconds integer not null check(cooldown_seconds>=3600), enabled boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.xp_claims (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_profiles(id), source text not null references public.xp_claim_types(id), reward integer not null check(reward>0), idempotency_key uuid not null, created_at timestamptz not null default now(), unique(user_id,idempotency_key));
insert into public.xp_claim_types(id,name,reward,cooldown_seconds) values ('daily','Daily reward',500,86400) on conflict(id) do nothing;
create table if not exists public.feedback (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_profiles(id), product_id uuid references public.products(id), type text not null check(type in ('product','experience','support')), title text not null default '' check(length(title)<=25), image_path text not null, status text not null default 'published' check(status in ('published','hidden','deleted')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.feedback_replies (id uuid primary key default gen_random_uuid(), feedback_id uuid not null references public.feedback(id), user_id uuid not null references public.user_profiles(id), body text not null check(length(body) between 1 and 1000), created_at timestamptz not null default now());
create table if not exists public.feedback_likes (feedback_id uuid not null references public.feedback(id), user_id uuid not null references public.user_profiles(id), created_at timestamptz not null default now(), primary key(feedback_id,user_id));
create table if not exists public.feedback_reports (id uuid primary key default gen_random_uuid(), feedback_id uuid not null references public.feedback(id), user_id uuid not null references public.user_profiles(id), reason text not null check(length(reason) between 3 and 500), created_at timestamptz not null default now(), unique(feedback_id,user_id));
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.user_profiles(id), action text not null, entity_id uuid, detail jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.activity_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_profiles(id), action text not null, created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_profiles(id), title text not null, body text not null, event_key text not null, read_at timestamptz, created_at timestamptz not null default now(), unique(user_id,event_key));
create table if not exists public.team_members (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 100), role text not null check(length(role) between 2 and 100), image text not null, discord_url text not null check(discord_url like 'https://discord.com/%' or discord_url like 'https://discord.gg/%'), created_at timestamptz not null default now());
create table if not exists public.contact_messages (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.user_profiles(id), email text not null, name text not null check(length(name) between 2 and 100), message text not null check(length(message) between 10 and 5000), image_path text, created_at timestamptz not null default now());
create table if not exists public.rate_limits (user_id uuid not null references public.user_profiles(id), action text not null, window_start timestamptz not null, hits integer not null default 1, primary key(user_id,action,window_start));
create index if not exists profiles_username_prefix on public.user_profiles(lower(username) text_pattern_ops);
create index if not exists licenses_creator_time on public.licenses(creator_id,created_at desc);
create index if not exists activations_user_product on public.license_activations(user_id,product_id,expires_at);
create index if not exists orders_user_time on public.orders(user_id,created_at desc);
create index if not exists claims_user_source_time on public.xp_claims(user_id,source,created_at desc);
create index if not exists feedback_time on public.feedback(status,created_at desc);
create index if not exists replies_post_time on public.feedback_replies(feedback_id,created_at);
create index if not exists reseller_user_window on public.reseller_access(user_id,ends_at);
create index if not exists notifications_user_time on public.notifications(user_id,created_at desc);
create or replace function public.mvp_touch() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now(); return new; end;$$;
do $$declare t text; begin foreach t in array array['user_profiles','products','licenses','reseller_access','subscriptions','orders','product_files','feedback','xp_accounts','store_settings'] loop if not exists(select 1 from pg_trigger where tgname='mvp_touch_'||t) then execute format('create trigger %I before update on public.%I for each row execute function public.mvp_touch()', 'mvp_touch_'||t,t); end if; end loop; end;$$;
-- All application tables have RLS. Writes are restricted to server-side functions; no frontend mutation grant.
do $$declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end;$$;
grant select on public.user_profiles to authenticated;
grant select on public.products,public.product_plans,public.team_members to anon,authenticated;
do $$declare t text; r text; begin foreach t in array array['products','product_plans','team_members'] loop foreach r in array array['anon','authenticated'] loop if not exists(select 1 from pg_policies where tablename=t and policyname=r||'_select_public_catalog') then execute format('create policy %I on public.%I for select to %I using (true)',r||'_select_public_catalog',t,r); end if; end loop; end loop; end;$$;
-- No direct grants for private hashes, user directory, XP writes, audit edits, or private storage paths.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('mvp-private','mvp-private',false,104857600,array['application/zip','application/x-zip-compressed','application/octet-stream']),('mvp-proofs','mvp-proofs',false,5242880,array['image/jpeg','image/png','image/webp']),('mvp-feedback','mvp-feedback',false,5242880,array['image/jpeg','image/png','image/webp']),('mvp-contact','mvp-contact',false,5242880,array['image/jpeg','image/png','image/webp']),('mvp-avatars','mvp-avatars',true,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
-- Storage operations are performed using signed uploads issued by the validated server. Avatars are intentionally public.
create or replace function public.mvp_is_admin(p_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_roles where user_id=p_user and role='admin');$$;
create or replace function public.mvp_active_reseller(p_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from reseller_access where user_id=p_user and status='active' and starts_at<=now() and ends_at>now());$$;
revoke all on function public.mvp_is_admin(uuid),public.mvp_active_reseller(uuid) from public,anon,authenticated;
grant execute on function public.mvp_is_admin(uuid),public.mvp_active_reseller(uuid) to service_role;
